"""Author PRE_A1-U15 only; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][14]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(14,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U15.UNDERSTAND';A='PRE_A1.U15.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('soleil','fr:soleil:sun','le soleil','солнце','лё солэ́й',ex('Il y a du soleil.','Солнечно.','иль я дю солэ́й'),1,[rev('soleil-meaning',fr('Le soleil','лё солэ́й'),['Дождь','Солнце','Снег'],1,'Названо солнце.','Правильное значение — солнце; дождь и снег называются иначе.'),rev('soleil-use',ru('Нужно полной изученной фразой сообщить «Солнечно». Что выбрать?'),[fr('Il pleut.','иль плё́'),fr('Le soleil.','лё солэ́й'),fr('Il y a du soleil.','иль я дю солэ́й')],2,'Полная погодная фраза сообщает, что солнечно.','Нужна полная фраза о солнечной погоде; дождь и отдельное название солнца не соответствуют требуемому образцу.')])
addword('il-pleut','fr:il-pleut:raining','il pleut','идёт дождь','иль плё́',ex('Il pleut.','Идёт дождь.','иль плё́'),1,[rev('il-pleut-meaning',fr('Il pleut.','иль плё́'),['Идёт дождь','Солнечно','Тепло'],0,'Фраза сообщает, что идёт дождь.','Правильный смысл — идёт дождь; солнце и температура этой фразой не названы.'),rev('il-pleut-use',ru('В условии идёт дождь. Какой полной изученной фразой сообщить это?'),[fr('Il y a du soleil.','иль я дю солэ́й'),fr('Il pleut.','иль плё́'),fr('Le soleil.','лё солэ́й')],1,'Выбрана фраза о дожде.','Нужно сообщение о дожде; название солнца и фраза о солнечной погоде имеют другой смысл.')])
addword('vent','fr:vent:wind','le vent','ветер','лё ва́(н)',ex('Il y a du vent.','Ветрено.','иль я дю ва́(н)'),3,[rev('vent-meaning',fr('Le vent','лё ва́(н)'),['Солнце','Ветер','Дождь'],1,'Назван ветер.','Правильное значение — ветер; солнце и дождь обозначаются иначе.'),rev('vent-use',ru('Нужно полной изученной фразой сообщить «Ветрено». Что выбрать?'),[fr('Il y a du soleil.','иль я дю солэ́й'),fr('Il pleut.','иль плё́'),fr('Il y a du vent.','иль я дю ва́(н)')],2,'Полная фраза сообщает о ветре.','Нужна фраза о ветре; солнце и дождь не соответствуют условию.')])
addword('il-neige','fr:il-neige:snowing','il neige','идёт снег','иль нэ́ж',ex('Il neige.','Идёт снег.','иль нэ́ж'),3,[rev('il-neige-meaning',fr('Il neige.','иль нэ́ж'),['Идёт снег','Идёт дождь','Ветрено'],0,'Фраза сообщает, что идёт снег.','Правильный смысл — идёт снег; дождь и ветер названы другими фразами.'),rev('il-neige-use',ru('В условии идёт снег. Как сообщить это изученной фразой?'),[fr('Il y a du vent.','иль я дю ва́(н)'),fr('Il neige.','иль нэ́ж'),fr('Il pleut.','иль плё́')],1,'Выбрана фраза о снегопаде.','Нужно сообщение о снеге; ветер и дождь меняют условие.')])
addword('quel-temps','fr:quel-temps-fait-il:weather-question','quel temps fait-il ?','какая погода? (готовый вопрос)','кэль та(н) фэ ти́ль',ex('Quel temps fait-il aujourd’hui ?','Какая сегодня погода?','кэль та(н) фэ тиль ожурдюи́'),4,[rev('quel-temps-meaning',fr('Quel temps fait-il ?','кэль та(н) фэ ти́ль'),['Сообщение, что идёт дождь','Вопрос о дне встречи','Вопрос о погоде'],2,'Это готовый вопрос о погоде.','Фраза спрашивает о погоде; она не сообщает дождь и не спрашивает о дне встречи.'),rev('quel-temps-use',ru('Вы хотите узнать, какая сегодня погода. Какой изученный вопрос выбрать?'),[fr('Quel temps fait-il aujourd’hui ?','кэль та(н) фэ тиль ожурдюи́'),fr('Rendez-vous quand ?','ра(н)дэ-ву ка́(н)'),fr('Il pleut.','иль плё́')],0,'Выбран вопрос о сегодняшней погоде.','Нужен вопрос о погоде сегодня; вопрос о встрече и сообщение о дожде выполняют другую функцию.')])

def cards(ids):return [wc(x) for x in ids]
s=start(1,'Различайте солнечную погоду и дождь в коротких фразах. Повторите знакомую утреннюю рамку распорядка.',['soleil','il-pleut','matin','je','lire','livre'])
choose(s,'reading',['PRE_A1.U14.UNDERSTAND'],['matin','je','lire','livre'],['matin'],'Когда происходит чтение в знакомом образце?',fr('Le matin, je lis un livre.','лё матэ(н), жё ли э(н) ли́вр.'),['Вечером','Утром','Ночью'],1,'Чтение отнесено к утру.','В начале знакомая утренняя рамка; вечер и ночь названы иначе.')
intro(s,2,'Le soleil — «солнце». Готовая погодная фраза Il y a du soleil. означает «Солнечно». Другая фраза Il pleut. — «Идёт дождь». Запоминайте полные образцы. Начало погодной фразы не указывает на человека: не переводим его как сообщение о том, что делает он. Форму названия солнца внутри образца сохраняем целиком, без общей таблицы артиклей.',['soleil','il-pleut'],[('Le soleil','лё солэ́й'),('Il y a du soleil.','иль я дю солэ́й'),('Il pleut.','иль плё́')],('Il y a du soleil. Il pleut.','иль я дю солэ́й. иль плё́.'))
phrase_pairs(s,[U],[('Le soleil','лё солэ́й','Солнце — название.',['soleil'],['soleil']),('Il y a du soleil.','иль я дю солэ́й.','Солнечно — полная погодная фраза.',['soleil'],['soleil']),('Il pleut.','иль плё́.','Идёт дождь.',['il-pleut'],['il-pleut'])],'Вы различили название солнца и две полные погодные фразы.','Отдельное название и полная фраза выполняют разные задачи; дождь обозначается своим целым образцом.')
listen(s,[U],['soleil','il-pleut'],['il-pleut'],'Что сообщает погодная фраза?','Il pleut.','иль плё́.',['Идёт дождь','Солнечно','Погода не названа'],0,'Фраза сообщает дождь.','Нужен смысл «Идёт дождь»; это законченное сообщение о погоде.')
choose(s,'vocabulary',[U],['soleil','il-pleut'],['soleil'],'Выберите полную изученную фразу «Солнечно».',ru('Нужна погодная фраза, а не отдельное название.'),[fr('Il pleut.','иль плё́.'),fr('Il y a du soleil.','иль я дю солэ́й.'),fr('Le soleil.','лё солэ́й.')],1,'Выбран полный образец о солнечной погоде.','Нужна полная фраза «Солнечно»; отдельное название солнца и дождь не соответствуют условию.')
choose(s,'reading',[U],['soleil','il-pleut'],['soleil'],'Какой смысл у записи?',fr('Il y a du soleil.','иль я дю солэ́й.'),['Идёт дождь','Время суток не указано, поэтому погоду понять нельзя','Солнечно'],2,'Запись сообщает солнечную погоду; время суток для этого ответа не требуется.','Погода названа прямо: солнечно. Не нужно выводить её из времени суток.')
fill(s,[U],['soleil','il-pleut'],['soleil'],'Восстановите показанный образец «Солнечно».','Il y a ','иль я́','','',[fr('du soleil','дю солэ́й'),fr('le soleil','лё солэ́й')],0,'Il y a du soleil','иль я дю солэ́й','Сохранено сочетание из полного погодного образца.','В показанном образце после начала используется форма с другим артиклем, чем отдельное словарное название; выберите целое изученное сочетание.')
order(s,[U],['soleil'],[],'Соберите полный образец «Солнечно». Начните с целого показанного начала погодной фразы.',[('Il y a','иль я́'),('du','дю'),('soleil.','солэ́й')],'Il y a du soleil.','иль я дю солэ́й.','Получилась полная погодная фраза.','Поставьте показанное начало первым, затем форму артикля из образца и название солнца.')
page(s,[('Солнце и солнечная погода',['Название солнца показано с артиклем. В полной погодной фразе сохраняется готовое сочетание из образца; общая таблица артиклей не требуется.'],[ex('Le soleil','Солнце','лё солэ́й'),W['soleil']['example']]),('Дождь',['Сообщение о дожде учится как короткая законченная фраза. Нужную погоду определяют слова, а не картинка или предполагаемое время суток.'],[W['il-pleut']['example']]),('Погодное начало',['В изученной погодной фразе начало не означает действующее лицо «он». Перенос значения из сообщения о человеке здесь не нужен.'],[ex('Il pleut.','Идёт дождь.','иль плё́')])])
s=start(2,'Понимайте сообщения о тёплой или жаркой и холодной погоде. Используйте знакомые слова температуры в новых готовых погодных образцах.',['chaud','froid','soleil','il-pleut'])
choose(s,'reading',[U],['soleil','il-pleut'],['soleil'],'Что сообщает знакомая погодная фраза?',fr('Il y a du soleil.','иль я дю солэ́й.'),['Идёт дождь','Солнечно','Температура обязательно высокая'],1,'Фраза сообщает солнечную погоду.','Солнце названо прямо; конкретная температура из этой фразы не следует.')
intro(s,2,'Знакомые слова температуры используем в новых полных образцах: Il fait chaud. — «Тепло; жарко» о погоде, Il fait froid. — «Холодно» о погоде. Точная температура не названа. Здесь не описывают температуру напитка и не сообщают действие человека. Для этих двух образцов сохраняйте показанное начало Il fait; солнечная погода остаётся в другом готовом образце Il y a du soleil.',['chaud','froid'],[('Il fait chaud.','иль фэ шо́'),('Il fait froid.','иль фэ фруа́'),('Il fait','иль фэ́'),('Il y a du soleil.','иль я дю солэ́й')],('Il fait chaud. Il fait froid.','иль фэ шо́. иль фэ фруа́.'))
phrase_pairs(s,[U],[('Il fait chaud.','иль фэ шо́.','Тепло или жарко — о погоде.',['chaud'],['chaud']),('Il fait froid.','иль фэ фруа́.','Холодно — о погоде.',['froid'],['froid']),('Il pleut.','иль плё́.','Идёт дождь.',['il-pleut'],['il-pleut'])],'Вы различили два сообщения о температуре и знакомый дождь.','Тепло или жарко противопоставлено холодной погоде; дождь сообщает о другом свойстве погоды.')
